describe('Mobile Landscape Orientation - Responsive Design', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display app content correctly in landscape orientation on mobile', () => {
    // Set viewport to a mobile device in landscape orientation
    cy.viewport('768x460');

    // Verify main content is visible and not cut off
    cy.get('[data-testid="main-content"]').should('be.visible');
    cy.get('[data-testid="header"]').should('be.visible');
    cy.get('[data-testid="footer"]').should('be.visible');

    // Verify layout elements are positioned correctly
    cy.get('[data-testid="navigation-menu"]').should('have.length', 1);
    cy.get('[data-testid="page-title"]').should('contain', 'Dashboard');

    // Verify no horizontal scrollbar appears
    cy.get('body').should('have.no-class', 'overflow-x');
    cy.get('body').should('not.have.class', 'overflow-x-hidden');

    // Verify content fits within the viewport width
    cy.get('[data-testid="main-content"]').should('have.width', '100%');
  });

  it('should handle content overflow gracefully in landscape orientation', () => {
    // Set viewport to a mobile device in landscape orientation
    cy.viewport('760px', '400px');

    // Navigate to a page with potentially long content
    cy.get('[data-testid="nav-link-profile"]').click();

    // Verify content is still visible and scrollable vertically
    cy.get('[data-testid="profile-details"]').should('be.visible');
    cy.get('[data-testid="profile-details"]').should('have.height', 'auto');

    // Verify vertical scrollbar is present and functional
    cy.get('body').should('have.class', 'overflow-y-scroll');
    cy.get('[data-testid="profile-details"]').then(($el) => {
      const height = $el.height();
      const scrollHeight = $el[0].scrollHeight;
      expect(height).to.be.lessThan(scrollHeight);
    });

    // Verify no horizontal scrollbar appears
    cy.get('body').should('not.have.class', 'overflow-x-hidden');
  });
});
